/**
 * VELOS — Locale: ja
 *
 * All UI strings for the ja locale, split by dictionary the same way the
 * inline en/sr/tr/de/ru blocks are split in dictionaries.ts and domains/*.ts.
 * Export names map 1:1 to the source dictionaries:
 *   NAV, SECTIONS, UI, DASHBOARD          -> src/lib/i18n/dictionaries.ts
 *   CRM, FINANCE, LOGISTICS, DOCUMENTS, ADMINISTRATION, PLATFORM, MISC,
 *   PORTAL, ERROR_AUDIT                    -> src/lib/i18n/domains/*.ts
 *
 * MERGED at build time by dictionaries.ts + domains/*.ts — no runtime lookup
 * cost. Missing keys fall back to English at runtime via t().
 *
 * Translation quality bar (business-grade, NOT generic machine tone):
 *  - Use the established terminology of international trade: proforma,
 *    Incoterms, RFQ, bill of lading, KYC/AML, letter of credit, HS code…
 *  - Preserve every {placeholder} and \n exactly as in the English source.
 *  - Keep brand names (VELOS, Aspidus) and widely-used industry acronyms
 *    (API, KYC, HS, SWIFT) as-is where that is the professional norm.
 *  - Formal, professional register appropriate for B2B trade software.
 */

